with d as (select value r from jsonb_array_elements($q$[{"notes":["Tepsi galay is best served warm from the dish. If you don't have an ovenproof dish, brown the meat in a frying pan and transfer to a large baking dish before adding the other ingredients.","The okra really does need to go in at the end, if you add it earlier it will break down and make the sauce slimy. Don't stir once the okra is in.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"id":"0e53d2ca-c88c-48db-b821-7a3e1944e3dc"},{"notes":["Make it fresh each time, sambal matah is best eaten within an hour of pounding, while the shallots still have bite.","Adjust the heat by using fewer chillies, or add a splash more lime juice if you prefer it sharper than hot."],"steps":[{"text":"Combine the sliced shallots, chopped bird's eye chillies and sliced garlic in a mortar or bowl."},{"text":"Using a pestle or the back of a spoon, gently pound to release the oils and aromas, about 1 to 2 minutes, until the ingredients are bruised, glistening and beginning to break down. You want them bruised, not completely crushed."},{"text":"Stir in the lime juice, neutral oil and salt. Taste and adjust salt or lime to your liking, it should be sharp, hot and bright."},{"text":"Leave to sit for a few minutes before serving so the flavours marry, then stir through fresh coriander if you like. Serve at room temperature with rice, grilled fish or sate."}],"id":"249ec2e8-86ac-489d-b5d0-b88b82542cf3"},{"steps":[{"text":"Line a fine sieve with cheesecloth or a clean tea towel. Pour the yoghurt into it, add the salt, and stir gently to combine. Tie the corners of the cloth together and hang it over a bowl (or suspend it in the fridge) to drain overnight, or for at least 12 hours, until the whey has stopped dripping. You want all the whey to drip away; the longer it strains, the thicker and more cheese-like the labaneh becomes."},{"text":"Once drained, the labaneh will be thick and creamy. Scrape it into a bowl and stir it smooth. You can serve it at this point, or for a richer texture and more authentic presentation, roll it into balls about the size of walnuts. Chill them for at least 1 hour so they hold their shape."},{"text":"Just before serving, arrange the balls on a plate or in a shallow dish. Sprinkle the za'atar evenly over the top, then drizzle generously with olive oil. The za'atar will stick to the oil and stay bright. Serve immediately with warm flatbread or pita for dipping, the bread is how you eat labaneh, never with a spoon alone."}],"id":"fb054b34-3968-4ec8-baa3-4b8de46cc29c"},{"steps":[{"text":"Rinse the sushi rice under cold water until the water runs almost clear. Cook in 360 ml water in a rice cooker or pot, about 15 minutes for a cooker or 20 minutes on the stove with the lid on."},{"text":"While the rice cooks, bring the dashi, soy sauce, caster sugar, mirin and sake to a gentle simmer. Carefully open each tofu pouch along the folded edge with your fingernail or a small knife, then slide them into the liquid. Poach for 8 to 10 minutes until they absorb the broth and soften, turning halfway. Set aside to cool until you can handle them, about 5 minutes."},{"text":"As the rice finishes, whisk the rice vinegar, salt and caster sugar together. Turn the hot rice into a shallow bowl and gently fold in the vinegar mixture, using a wooden spatula to cool it as you fold. This takes about 5 minutes. Let it rest while you prepare the filling."},{"text":"Dice the carrot, daikon and mushroom very finely, about the size of a sesame seed. If you like, blanch them in boiling water for 1 minute, then drain well. This keeps them crisp."},{"text":"Fold the diced vegetables, pickled ginger if using, sesame seeds, salt and white pepper gently through the cooled rice."},{"text":"Gently squeeze the tofu pockets to remove any excess broth. Hold one open and, using a small spoon, carefully fill each pocket with a modest amount of rice mixture, it should be gentle and not packed tight. The pocket should be full enough to hold its shape but not bursting."},{"text":"Arrange the filled pockets, seam-side up, on a plate. Serve at room temperature."}],"id":"a972ada1-da68-46cf-a3c0-c53e62524f0a"},{"notes":["Cassava fries are best eaten fresh and hot. If making ahead, reheat them in a 180°C oven for 5 minutes to restore crispness.","Don't skip soaking the cassava, it removes starch and makes the fries crispier."],"id":"da71901c-b669-479d-8c44-1e5724fff965"},{"notes":["Serve with crusty bread to soak up the sauce, or over rice or mash.","Makes great leftovers. Cool and store in the fridge for up to 3 days.","Works just as well in a camp oven at low heat, about 3 hours if the coals are right."],"id":"700238ad-81c1-4348-8789-ca88a30e50cd"},{"notes":["Make this a day ahead if you like, the flavour deepens overnight. Reheat gently on the stove or in a 160°C oven until warmed through.","Native pepper is available from good delis and spice shops, but if you can't find it, use a grind of black pepper instead.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"steps":[{"text":"Preheat the oven to 160°C. Pat the beef cheeks dry with paper towel, then season with salt and pepper."},{"text":"Heat the oil in a large heavy-bottomed pot or casserole dish over medium-high heat. Brown the beef cheeks in batches, 3 to 4 minutes each side, until golden. Transfer to a plate."},{"text":"Add the onions to the pot and cook until just coloured, about 4 minutes. Add the carrots and parsnips and stir for 2 minutes."},{"text":"Return the beef cheeks to the pot. Pour in the tinned tomatoes and beef stock, and add the bay leaves and thyme. The liquid should mostly cover the beef. Bring to a simmer until gentle bubbles break the surface."},{"text":"Cover and transfer to the oven. Cook for 3 hours, turning the beef cheeks halfway through, until they are very tender and the meat shreds easily with a fork."},{"text":"Remove from the oven. Stir through the ground native pepper. Taste and adjust seasoning with salt and pepper. Divide among bowls, spoon the gravy and vegetables over, and finish with a light grind of native pepper."},{"text":"Serve with mashed potato or crusty bread."}],"id":"0d9f69a3-fdc2-4bb6-bd5d-067197bb46a4"},{"notes":["Flaki tastes even better the next day. Make it ahead and reheat gently before serving.","Tripe should be cleaned already when you buy it, but if you have any doubt, rinse it well under cold water and rub gently with salt.","Some Kraków cooks add a little strong mustard or horseradish at the end. It's optional."],"id":"6932fc59-670d-48f6-a4e5-9a3dc74460d0"},{"notes":["This keeps well in the fridge for 2 days and reheats gently, add a splash of milk if it's thickened too much.","Traditionally you'd use the poaching liquid, as this recipe does."],"steps":[{"text":"Put the smoked haddock in a large saucepan with the milk and bay leaves. Bring gently to a simmer and cook for 8 minutes until the fish is just cooked through. Lift the fish out onto a plate, discard the skin and any bones, and break the flesh into flakes. Keep the milk in the pan."},{"text":"In a separate pan, melt the butter and cook the chopped onion gently, stirring occasionally, until soft and pale, about 5 minutes."},{"text":"Add the diced potatoes to the buttered onion and stir to coat. Pour in the reserved milk with the bay leaves, bring to a simmer and cook for about 12 minutes until the potatoes are tender."},{"text":"Return the flaked haddock to the pan, add the cream and stir gently. Heat through for 2–3 minutes without boiling."},{"text":"Season with salt and pepper to taste, go easy on the salt as the smoked fish is already quite salty. Serve hot, scattered with fresh parsley if you like."}],"id":"55b55b1b-d706-407a-af45-24c3bce283f6"},{"notes":["Make ahead: This actually tastes better the next day. Cool quickly, store in the fridge for up to 3 days, or freeze for up to 2 months. Add a splash of water when you reheat.","Brown lentils hold their shape better than red; French lentils work too. Skip the fancy stuff, everyday brown lentils from the market are perfect."],"id":"fcc4ff98-09d0-4068-9c82-add53a836973"},{"notes":["Best made the day before and reheated, the flavours deepen overnight.","Serve with Swedish mustard, rye bread, and a shot of aquavit if you're so inclined.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"steps":[{"text":"Rinse the split peas in cold water and drain. Place the pork, water, and bay leaf in a large pot and bring to a boil until a grey foam rises to the surface. Skim off any foam from the surface."},{"text":"Add the split peas, onions, carrots, and celery. Stir in the peppercorns and salt."},{"text":"Reduce the heat to low and simmer, partially covered, for about 2 hours, stirring occasionally. The peas should break down into the broth and the pork should be very tender."},{"text":"Taste and adjust seasoning with salt as needed. Serve hot in bowls with rye bread and Swedish mustard on the side."}],"id":"284deda7-6597-47c8-98e8-699d61f7e9dd"},{"notes":["Keep this in an airtight container in the fridge for up to 4 days, it reheats gently and actually improves as the flavours settle. Make it in bulk and freeze portions.","If you prefer less sweetness, use just 1 tbsp golden syrup, or substitute a splash of apple juice instead."],"id":"3546cff3-080b-481c-943e-0890d9d78c85"},{"notes":["Halwa keeps in an airtight container for 3–4 days. You can reheat it gently in a pan with a splash of water if it dries out.","The toasting of the semolina is important, it takes time but the flavour change is worth it. Don't rush it."],"steps":[{"text":"Heat the ghee in a large, heavy-based saucepan over medium heat. Add the semolina and stir constantly, breaking up any lumps. Toast for 8–10 minutes, stirring often, until the semolina is golden and smells nutty."},{"text":"Add the crushed cardamom pods and salt, stirring for 30 seconds to release the flavour."},{"text":"Carefully pour in the water, it will bubble, and stir constantly to combine. The mixture will be thick and pasty."},{"text":"Add the caster sugar and stir until it dissolves completely into the semolina mixture, about 2 minutes."},{"text":"Remove from the heat and fold through most of the almonds and raisins, reserving some for the top."},{"text":"Spoon the halwa into a serving dish and smooth the surface. Scatter the remaining almonds and raisins over the top."},{"text":"Let it cool to warm, then serve. It sets as it cools but stays soft inside."}],"id":"905a18c9-fc62-4d95-861b-9b997cb65f50"},{"notes":["Make this ahead: gumbo tastes even better the next day. Reheat gently on the stove, and stir in the filé powder just before serving.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large, heavy-bottomed pot over medium heat. Add the flour slowly, stirring constantly with a wooden spoon. Keep stirring, don't walk away, until the roux is deep chocolate brown, about 30 to 40 minutes. It'll go from light tan to darker shades; when it smells nutty and toasted, you're close."},{"text":"Add the onion, celery and capsicum to the roux. Stir well and cook, stirring often, until the vegetables are soft and golden, about 8 minutes."},{"text":"Add the chicken and sausage. Stir to coat with roux, and cook for 5 minutes."},{"text":"Pour in the stock slowly, stirring constantly until smooth to break up any lumps. Add the bay leaf, thyme and cayenne. Bring to a simmer, then reduce heat to low."},{"text":"Simmer gently, uncovered, for about 40 minutes, until the chicken is cooked through and the flavours have melded. Skim any fat from the surface if you like."},{"text":"Taste and season with salt and pepper. Remove from heat and stir in the filé powder until smooth. Don't boil after adding filé, or it gets stringy."},{"text":"Serve in bowls over white rice, scattered with spring onion if you like."}],"id":"50c05896-857b-407f-b9bc-eb72f5fcad18"},{"notes":["Tastes even better the next day. Reheat gently on the stove.","Traditional Colombian comfort food: serve with white rice and avocado on the side.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"4789d99e-a533-4789-a3be-1766c886c02d"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;